<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { useRoute } from 'vue-router'
import { derivarTarea, detalleTarea, finalizarTarea, liberarTarea, listarTareas, recibirTarea } from '../services/tareas'
import type { Options, Tarea } from '../interfaces/tareas.interface'
const route=useRoute(),rows=ref<Tarea[]>([]),options=ref<Options>({secciones:[],tipos_tarea:[],personal:[],estados:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),detail=ref<Tarea|null>(null),actionModal=ref<'finalizar'|'derivar'|null>(null),files=ref<File[]>([])
const filters=reactive({bandeja:route.query.bandeja==='mis-pendientes'?'mis-pendientes':'disponibles',criterio:'',seccion_id:'',tipo_tarea_id:'',estado:'',desde:'',hasta:'',page:1}),finish=reactive({detalle:'',personal:[] as number[],fecha_atencion:'',latitud:'',longitud:'',ok:true}),derive=reactive({seccion_id:'',detalle:''})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarTareas(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
async function show(item:Tarea){try{detail.value=await detalleTarea(item.id)}catch(e){error.value=message(e)}}async function action(item:Tarea,type:'recibir'|'liberar'){if(!confirm(`¿Confirmar ${type} la tarea #${item.id}?`))return;try{type==='recibir'?await recibirTarea(item.id):await liberarTarea(item.id);success.value='Tarea actualizada correctamente.';detail.value=null;await load()}catch(e){error.value=message(e)}}
function openFinish(item:Tarea){detail.value=item;Object.assign(finish,{detalle:item.respuesta||'',personal:item.personal?.map(x=>x.id)||[],fecha_atencion:'',latitud:'',longitud:'',ok:true});files.value=[];actionModal.value='finalizar'}function openDerive(item:Tarea){detail.value=item;Object.assign(derive,{seccion_id:'',detalle:''});actionModal.value='derivar'}
async function submit(){if(!detail.value)return;saving.value=true;error.value='';try{if(actionModal.value==='derivar'){if(!derive.seccion_id){error.value='Seleccione la sección de destino.';return}await derivarTarea(detail.value.id,derive)}else{if(finish.detalle.trim().length<5){error.value='El detalle debe tener al menos 5 caracteres.';return}const data=new FormData();data.append('detalle',finish.detalle);data.append('ok',finish.ok?'1':'0');if(finish.fecha_atencion)data.append('fecha_atencion',finish.fecha_atencion);if(finish.latitud)data.append('latitud',finish.latitud);if(finish.longitud)data.append('longitud',finish.longitud);finish.personal.forEach(x=>data.append('personal[]',String(x)));files.value.forEach(x=>data.append('evidencias[]',x));await finalizarTarea(detail.value.id,data)}success.value=actionModal.value==='derivar'?'Tarea derivada correctamente.':'Tarea finalizada correctamente.';actionModal.value=null;detail.value=null;await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
function pick(e:Event){files.value=Array.from((e.target as HTMLInputElement).files||[])}function togglePerson(id:number){finish.personal=finish.personal.includes(id)?finish.personal.filter(x=>x!==id):[...finish.personal,id]}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Tareas</nav><header class="hero"><div class="mark">TA</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Bandeja de tareas</h1><p>Recepción, derivación y ejecución de actividades del flujo comercial.</p></div><strong>{{total}} tareas</strong></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div class="tabs"><button v-for="x in [{id:'disponibles',name:'Disponibles'},{id:'mis-pendientes',name:'Mis pendientes'},{id:'por-asignar',name:'Por asignar'},{id:'finalizadas',name:'Finalizadas'}]" :key="x.id" :class="{active:filters.bandeja===x.id}" @click="filters.bandeja=x.id;load(1)">{{x.name}}</button></div><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Tarea, ticket o descripción" @keyup.enter="load(1)"></label><label>Sección<select v-model="filters.seccion_id"><option value="">Todas</option><option v-for="x in options.secciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo<select v-model="filters.tipo_tarea_id"><option value="">Todos</option><option v-for="x in options.tipos_tarea" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando tareas…</div><div v-else-if="!rows.length" class="empty">No existen tareas en esta bandeja.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id"><header><div><small>{{item.seccion||item.origen}}</small><b>Tarea #{{item.id}}</b></div><em>{{item.estado}}</em></header><h2>{{item.accion||item.tipo_tarea}}</h2><p>{{item.descripcion||'Sin indicaciones adicionales.'}}</p><dl><div><dt>Cliente</dt><dd>{{item.cliente||'—'}}</dd></div><div><dt>Ubicación</dt><dd>{{item.distrito||'—'}} · {{item.direccion||'—'}}</dd></div><div><dt>Enviada por</dt><dd>{{item.usuario_envia||'—'}}</dd></div><div><dt>Programada</dt><dd>{{item.fecha_programacion||'Sin fecha'}}</dd></div></dl><footer><button @click="show(item)">Ver</button><button v-if="item.puede_recibir" class="good" @click="action(item,'recibir')">Recibir</button><button v-if="item.puede_liberar" @click="action(item,'liberar')">Liberar</button><button v-if="item.puede_derivar" @click="openDerive(item)">Derivar</button><button v-if="item.puede_finalizar" class="good" @click="openFinish(item)">Finalizar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="detail&&!actionModal" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>DETALLE DE TAREA</small><h2>Tarea #{{detail.id}} · {{detail.accion}}</h2><p>{{detail.estado}} · {{detail.responsable||'Sin responsable'}}</p></div><button @click="detail=null">×</button></header><p class="description">{{detail.descripcion}}</p><div class="summary"><div><b>{{detail.ticket_id||detail.documento_id||'—'}}</b><span>Origen</span></div><div><b>{{detail.personal?.length||0}}</b><span>Participantes</span></div><div><b>{{detail.adjuntos?.length||0}}</b><span>Evidencias</span></div><div><b>{{detail.fecha_atencion||'Pendiente'}}</b><span>Atención</span></div></div><h3>Respuesta</h3><p>{{detail.respuesta||'Aún no se registra una respuesta.'}}</p><h3>Historial</h3><div class="list"><div v-for="x in detail.logs" :key="x.id"><b>{{x.accion}}</b><span>{{x.usuario}} · {{x.fecha}}</span></div></div><h3>Evidencias</h3><div class="list"><div v-for="x in detail.adjuntos" :key="x.id"><b>{{x.nombre}}</b><span>{{x.archivo}}</span></div></div><footer><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.puede_liberar" @click="action(detail,'liberar')">Liberar</button><button v-if="detail.puede_derivar" @click="openDerive(detail)">Derivar</button><button v-if="detail.puede_finalizar" @click="openFinish(detail)">Finalizar</button></footer></section></div>
<div v-if="actionModal&&detail" class="backdrop" @mousedown.self="actionModal=null"><form class="modal" @submit.prevent="submit"><header><div><small>TAREA #{{detail.id}}</small><h2>{{actionModal==='derivar'?'Derivar tarea':'Finalizar atención'}}</h2></div><button type="button" @click="actionModal=null">×</button></header><template v-if="actionModal==='derivar'"><label>Sección de destino *<select v-model="derive.seccion_id"><option value="">Seleccione</option><option v-for="x in options.secciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Indicaciones<textarea v-model.trim="derive.detalle" rows="5"></textarea></label></template><template v-else><label>Detalle de atención *<textarea v-model.trim="finish.detalle" minlength="5" rows="5"></textarea></label><div class="grid"><label>Fecha de atención<input v-model="finish.fecha_atencion" type="datetime-local"></label><label class="check"><input v-model="finish.ok" type="checkbox"> Atención con solución</label><label>Latitud<input v-model="finish.latitud" type="number" step="any"></label><label>Longitud<input v-model="finish.longitud" type="number" step="any"></label></div><h3>Personal participante</h3><div class="people"><button v-for="x in options.personal" :key="x.id" type="button" :class="{selected:finish.personal.includes(x.id)}" @click="togglePerson(x.id)">{{x.nombre}} <b>{{finish.personal.includes(x.id)?'✓':''}}</b></button></div><label>Evidencias<input type="file" multiple accept="image/*,video/*" @change="pick"><small>Imágenes o videos, máximo 20 MB por archivo.</small></label></template><footer><button type="button" class="clear" @click="actionModal=null">Cancelar</button><button :disabled="saving">{{saving?'Procesando…':'Confirmar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#21a06b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.tabs{margin-top:13px;display:flex;gap:4px}.tabs button{padding:10px 16px;border:0;border-radius:7px 7px 0 0;color:#718087;background:#e7ebed;font-size:.56rem}.tabs button.active{color:#fff;background:var(--accent)}.filters{padding:12px;display:flex;align-items:end;gap:7px;border-radius:0 9px 9px 9px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.59rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-top:3px solid var(--accent);border-radius:9px;background:#fff}.cards article>header{display:flex;justify-content:space-between}.cards header small,.cards header b{display:block}.cards header em{padding:4px 7px;border-radius:10px;background:#eff9f4;font-size:.48rem;font-style:normal}.cards h2{font-size:.64rem}.cards article>p{min-height:38px;color:#69777d;font-size:.55rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cards dt{color:#8a969c;font-size:.46rem}.cards dd{margin:2px 0;font-size:.51rem;font-weight:700}.cards footer{margin-top:auto;display:flex;justify-content:flex-end}.cards footer button{border:0;color:#65747b;background:none;font-size:.49rem}.cards footer .good{color:var(--accent)}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;color:#879399}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.check{display:flex!important;align-items:center;gap:6px}.check input{width:auto}.description{padding:11px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.57rem}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#eff9f4}.summary b,.summary span{display:block;font-size:.53rem}.modal h3{font-size:.65rem}.list div{padding:8px;display:flex;justify-content:space-between;border-bottom:1px solid #edf0f2;font-size:.53rem}.list span{color:#7d898f}.people{max-height:140px;overflow:auto;margin-bottom:12px}.people button{width:100%;padding:7px;display:flex;justify-content:space-between;border:0;border-bottom:1px solid #e8ecee;background:#fff;text-align:left;font-size:.52rem}.people button.selected{background:#eff9f4}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.detail{width:min(100%,900px)}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}}@media(max-width:560px){.cards,.grid,.summary{grid-template-columns:1fr}.tabs{overflow:auto}}
</style>
